SELECT * FROM `illustration`

    `user_id`=#{userId}
    AND `deleted`=#{deleted}

ORDER BY `sort_order` DESC, `id` DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT `id` FROM `illustration`
WHERE `deleted` = 1 AND `update_time` <= #{cutoff,jdbcType=TIMESTAMP}
ORDER BY `update_time`, `id`

SELECT * FROM `illustration`
WHERE `id` = #{id}
  AND `deleted` = 1
  AND `update_time` <= #{cutoff,jdbcType=TIMESTAMP}
FOR UPDATE

mapper.update:
UPDATE `illustration`
SET `sort_order` = `sort_order` - 1,
    `update_time` = `update_time`
WHERE `user_id` = #{userId}
  AND `sort_order` > #{oldSortOrder}
  AND `sort_order` <= #{targetSortOrder}
ORDER BY `sort_order` ASC

UPDATE `illustration`
SET `sort_order` = `sort_order` + 1,
    `update_time` = `update_time`
WHERE `user_id` = #{userId}
  AND `sort_order` >= #{targetSortOrder}
  AND `sort_order` < #{oldSortOrder}
ORDER BY `sort_order` DESC
